using JTradeERP.Application.Common.Exceptions;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Features.Billing.NumberSeries.Common;using MediatR;namespace JTradeERP.Application.Features.Billing.NumberSeries.UpdateNumberSeries;public sealed class UpdateNumberSeriesHandler(IApplicationDbContext db):IRequestHandler<UpdateNumberSeriesCommand,UpdateNumberSeriesResponse>{public async Task<UpdateNumberSeriesResponse> Handle(UpdateNumberSeriesCommand r,CancellationToken ct){var x=db.NumberSeries.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Number series not found.");if(db.NumberSeries.Any(x=>x.Id!=r.Id&&x.DocumentType==r.DocumentType.Trim()))throw new ConflictException("Document number series already exists.");x.Update(r.DocumentType,r.Prefix,r.NextNumber,r.Padding);await db.SaveChangesAsync(ct);return new(new(x.Id,x.DocumentType,x.Prefix,x.NextNumber,x.Padding));}}
